/* Working-page shell. GENERATED by the portal's build script; do not edit by hand.
   Generic: nothing in this file names a client or a person, and it holds no wording from the page.
   The cards, the boxes and every word arrive from the API after sign-in. A browser in consultant mode
   (the same once-per-browser flag the other pages use) can change a call, a wording or a box; each
   change is sent about a second after the last keystroke and kept on the server as one more row.
   Everyone else gets the same page read-only and one comment box. */
(function () {
  "use strict";
  var R = window.RAM;
  var TEST = R.TEST_MODE && /[?&]as=TEST(&|$)/.test(location.search);
  var EDIT = !!R.DALE_MODE;
  var Q = TEST ? "?as=TEST" : "";
  var SEC = 1e3;
  var KIND = { v: "verdict", w: "wording", b: "box" };
  var who = "", loadedHash = "", order = [];
  var areas = [], radios = [], cards = [];
  var dirty = {}, refused = {}, lastGood = null, timer = null, retry = null, busy = false, gen = 0;

  function $(id) { return document.getElementById(id); }
  function mk(tag, cls, text) { var n = document.createElement(tag); if (cls) n.className = cls; if (text !== undefined && text !== null) n.textContent = text; return n; }
  function all(sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); }
  function clock() { return new Date().toLocaleTimeString([], { hour: "numeric", minute: "2-digit" }); }
  function fail(text) { document.body.insertBefore(mk("p", "ufail", text), document.body.firstChild); }
  function auth(extra) { var h = extra || {}; h["Authorization"] = "Bearer " + R.getToken(); return h; }
  function answer(r) { return r.json().catch(function () { return {}; }).then(function (j) { return { s: r.status, j: j }; }); }
  function pending() { return Object.keys(dirty).length > 0; }

  R.gate(function () {
    R.apiJSON("/ude/board" + Q).then(function (d) {
      if (!d || !d.ok || !d.content || !d.state) throw new Error((d && d.error) || "The page could not be loaded.");
      start(d);
    }).catch(function (e) { if (e && e.message !== "signed out") fail(e.message || "The page could not be loaded."); });
  });

  function start(d) {
    var C = d.content;
    who = TEST ? "TEST" : (EDIT ? (d.editor || "") : "");
    loadedHash = d.content_hash || "";
    order = C.verdict_order || [];
    ["gate", "app", "gateCss"].forEach(function (id) { var n = $(id); if (n) n.parentNode.removeChild(n); });
    var css = document.createElement("link");
    css.rel = "stylesheet"; css.href = "../assets/ude.css?v=8bfa652a62";
    var go = function () {
      go = function () { };
      document.title = C.title || document.title;
      document.body.classList.add(EDIT ? "ed" : "ro");
      var holder = document.createElement("template");
      holder.innerHTML = C.body_html;
      document.body.insertBefore(holder.content, document.body.querySelector("script"));
      if (!EDIT) (C.viewer_text || []).forEach(function (v) {
        try { all(v.selector).forEach(function (n) { n.textContent = v.text; }); } catch (e) { }
      });
      var nav = mk("div", "unav");
      nav.appendChild(mk("span", "umode", EDIT ? "Editing: changes save as you make them" : "Read only"));
      var notice = mk("span", "unotice"); notice.id = "udeNotice"; notice.hidden = true; nav.appendChild(notice);
      var home = mk("a", null, "Home"); home.href = "../"; nav.appendChild(home);
      var out = mk("a", null, "Sign out"); out.href = "#"; out.setAttribute("data-action", "signout"); nav.appendChild(out);
      document.body.insertBefore(nav, document.body.firstChild);
      try { wire(d); } catch (e) { fail("The page could not be drawn: " + e.message); throw e; }
      if (EDIT) editorExtras(); else { lock(); viewerExtras(C, d.names || []); }
      document.body.setAttribute("data-ude-ready", EDIT ? "edit" : "view");
    };
    css.onload = function () { go(); };
    css.onerror = function () { go(); };
    document.head.appendChild(css);
  }

  /* ---------- status line: it rides in the sticky counter strip so it is always on screen ---------- */
  function note(text, kind) {
    var n = $("udeStatus");
    if (n) { n.textContent = text; n.className = "ustat" + (kind === "bad" ? " bad" : ""); }
    document.body.setAttribute("data-save-state", kind || "ok");
  }

  /* ---------- boxes: a twin for paper, and a height that follows the text ---------- */
  function mirror(t) { if (t.pvTwin) t.pvTwin.textContent = t.value; }
  function grow(t) {
    if (!t.offsetWidth) return;
    var y = window.pageYOffset;
    t.style.height = "auto";
    t.style.height = (t.scrollHeight + 4) + "px";
    if (window.pageYOffset !== y) window.scrollTo(window.pageXOffset, y);
  }
  function growAll() { areas.forEach(grow); }
  function paint() {
    var counts = {};
    order.forEach(function (v) { counts[v] = 0; });
    cards.forEach(function (card) {
      var v = "";
      all('input[type="radio"]', card).forEach(function (r) {
        if (r.checked) v = r.value;
        if (r.parentNode && r.parentNode.classList) r.parentNode.classList.toggle("on", r.checked);
      });
      card.setAttribute("data-verdict", v);
      if (counts.hasOwnProperty(v)) counts[v] += 1;
    });
    order.forEach(function (v) {
      var el = $("tally" + v.charAt(0).toUpperCase() + v.slice(1));
      if (el) el.textContent = String(counts[v]);
    });
  }

  /* ---------- the server's state onto the page; a box with focus or unsent text is left alone ---------- */
  function applyState(st) {
    if (!st) return;
    var sc = st.cards || {}, sb = st.boxes || {};
    cards.forEach(function (card) {
      var id = card.getAttribute("data-id"), s = sc[id];
      if (!s || dirty.hasOwnProperty("v:" + id) || refused.hasOwnProperty("v:" + id)) return;
      all('input[type="radio"]', card).forEach(function (r) { r.checked = (r.value === s.verdict); });
    });
    areas.forEach(function (t) {
      var key = t.udeKey, val = null;
      if (key.charAt(0) === "w") { if (sc[key.slice(2)]) val = sc[key.slice(2)].wording; }
      else if (sb[key.slice(2)]) val = sb[key.slice(2)].text;
      if (typeof val !== "string" || dirty.hasOwnProperty(key) || refused.hasOwnProperty(key)) return;
      if (document.activeElement === t && !t.readOnly) return;
      if (t.value !== val) { t.value = val; mirror(t); grow(t); }
    });
    paint();
  }
  function checkHash(h) {
    var n = $("udeNotice");
    if (!n || !h || !loadedHash || h === loadedHash) return;
    n.textContent = "This page has been updated. Reload to see the new version.";
    n.hidden = false;
  }

  function wire(d) {
    var strip = $("tally");
    var stat = mk("div", "ustat"); stat.id = "udeStatus"; stat.setAttribute("role", "status");
    if (strip) strip.appendChild(stat);
    cards = all("main .card");
    radios = all('main .card input[type="radio"]');
    areas = all("main textarea");
    areas.forEach(function (t) {
      var card = t.closest ? t.closest(".card") : null;
      t.udeKey = card ? "w:" + card.getAttribute("data-id") : "b:" + t.id;
      var pv = document.createElement("div");
      pv.className = "pv";
      pv.setAttribute("aria-hidden", "true");
      t.parentNode.insertBefore(pv, t.nextSibling);
      t.pvTwin = pv;
      mirror(t);
      t.addEventListener("input", function () {
        mirror(t); grow(t);
        if (EDIT) queue(t.udeKey, t.value);
      });
    });
    radios.forEach(function (r) {
      r.addEventListener("change", function () {
        if (!r.checked) return;
        paint();
        var card = r.closest ? r.closest(".card") : null;
        if (EDIT && card) queue("v:" + card.getAttribute("data-id"), r.value);
      });
    });
    applyState(d.state);
    growAll();
    all("details").forEach(function (x) {
      x.addEventListener("toggle", function () { if (x.open) all("textarea", x).forEach(grow); });
    });
    var resizeTimer = null;
    window.addEventListener("resize", function () { clearTimeout(resizeTimer); resizeTimer = setTimeout(growAll, 150); });
    window.addEventListener("load", growAll);
    setTimeout(growAll, 300);
    note(EDIT ? "Changes save as you make them." : "Read only. Current as of " + clock() + ".", "ok");
    window.addEventListener("pagehide", function () { if (EDIT && pending()) flush(true); });
    setInterval(refresh, 30 * SEC);
    window.addEventListener("focus", refresh);
    document.addEventListener("visibilitychange", function () { if (!document.hidden) refresh(); });
  }

  /* ---------- saving: each change is one more row on the server; "Saved" only after the server says so ---------- */
  function queue(key, value) {
    dirty[key] = value;
    delete refused[key];
    note("Saving...", "saving");
    clearTimeout(timer);
    timer = setTimeout(flush, SEC);
  }
  function post(keys, batch, leaving) {
    var events = keys.map(function (k) { return { kind: KIND[k.charAt(0)], id: k.slice(2), value: batch[k] }; });
    return fetch(R.API + "/ude/save" + Q, { method: "POST", keepalive: leaving === true,
      headers: auth({ "Content-Type": "application/json" }),
      body: JSON.stringify({ answered_by: who, events: events }) }).then(answer);
  }
  /* settle(): one answered request. Returns "" when it was saved, otherwise the plain reason. A single change the
     server refuses outright is set aside (and kept on screen) so it cannot hold up every later save. */
  function settle(keys, batch, x) {
    if (x.s === 200 && x.j && x.j.ok) {
      gen += 1;
      keys.forEach(function (k) { if (dirty[k] === batch[k]) delete dirty[k]; });
      var ids = (x.j.saved && x.j.saved.ids) || [];
      if (ids.length) document.body.setAttribute("data-saved-id", String(ids[ids.length - 1]));
      lastGood = x.j;
      return "";
    }
    if (x.s === 401) return "signed out. Reload the page and enter the password again";
    var why = String((x.j && x.j.error) || ("the server answered " + x.s)).replace(/\.$/, "");
    if (x.s === 400 && keys.length === 1) {
      if (dirty[keys[0]] === batch[keys[0]]) delete dirty[keys[0]];
      refused[keys[0]] = why;
      return "";
    }
    return why;
  }
  function flush(leaving) {
    clearTimeout(timer); timer = null;
    clearTimeout(retry); retry = null;
    if (busy) return;
    var keys = Object.keys(dirty);
    if (!keys.length) return;
    var batch = {}, failed = "";
    keys.forEach(function (k) { batch[k] = dirty[k]; });
    busy = true;
    post(keys, batch, leaving)
      .then(function (x) {
        if (x.s === 400 && keys.length > 1) {
          /* the server takes a request whole or not at all: send each change on its own so one bad one cannot block the rest */
          return keys.reduce(function (chain, k) {
            return chain.then(function () { return post([k], batch, false); }).then(function (y) { var w = settle([k], batch, y); if (w) failed = w; });
          }, Promise.resolve());
        }
        failed = settle(keys, batch, x);
      })
      .then(function () {
        busy = false;
        if (lastGood) { applyState(lastGood.state); checkHash(lastGood.content_hash); lastGood = null; }
        var n = Object.keys(refused).length;
        if (failed) note("Not saved: " + failed + ". The change is still on this screen.", "bad");
        else if (n) {
          note("Not saved: the server refused " + n + (n === 1 ? " change (" : " changes (") + refused[Object.keys(refused)[0]] +
            "). Everything else is saved. The refused text is still on this screen; copy it, then reload the page.", "bad");
          if (pending()) timer = setTimeout(flush, SEC);
        }
        else if (pending()) { note("Saving...", "saving"); timer = setTimeout(flush, SEC); }
        else note("Saved " + clock(), "saved");
      })
      .catch(function () {
        busy = false;
        note("Not saved: the server could not be reached. The change is still on this screen and will be sent again shortly.", "bad");
        retry = setTimeout(flush, 5 * SEC);
      });
  }

  /* ---------- live refresh: on a timer and when the tab gets focus; never while a change is on its way ---------- */
  function refresh() {
    if (busy || timer || retry || pending()) return;
    var g = gen;
    fetch(R.API + "/ude/board?part=state" + (TEST ? "&as=TEST" : ""), { headers: auth() })
      .then(answer)
      .then(function (x) {
        if (x.s === 401) { note("Signed out. Reload the page and enter the password again.", "bad"); return; }
        if (x.s !== 200 || !x.j || !x.j.ok) return;
        if (g !== gen || busy || pending()) return;
        applyState(x.j.state);
        checkHash(x.j.content_hash);
        document.body.setAttribute("data-refreshed", String(Date.now()));
        if (!EDIT) note("Read only. Current as of " + clock() + ".", "ok");
      })
      .catch(function () { });
    if (EDIT && drawComments) loadComments();
  }

  /* ---------- read only: nothing to press, nothing to type in ---------- */
  function lock() {
    radios.forEach(function (r) { r.disabled = true; });
    areas.forEach(function (t) { t.readOnly = true; t.setAttribute("aria-readonly", "true"); });
  }

  function addSection(id, heading) {
    var sec = mk("section", "panel urun"); sec.id = id;
    sec.appendChild(mk("h2", null, heading));
    var main = document.querySelector("main") || document.body, foot = main.querySelector("footer");
    if (foot && foot.parentNode === main) main.insertBefore(sec, foot); else main.appendChild(sec);
    return sec;
  }

  function viewerExtras(C, names) {
    var sec = addSection("uvComment", C.comment_label || "Say what is wrong");
    if (C.comment_help) sec.appendChild(mk("p", "umsg", C.comment_help));
    var ta = mk("textarea"); ta.id = "uvCommentText"; ta.rows = 4; ta.setAttribute("aria-label", C.comment_label || "Comment");
    sec.appendChild(ta);
    var row = mk("div", "urow"), sel = mk("select"), b = mk("button", null, "Send"), msg = mk("span", "umsg");
    sel.id = "uvCommentWho"; sel.setAttribute("aria-label", "Your name");
    var first = mk("option", null, "Your name"); first.value = ""; sel.appendChild(first);
    (TEST ? ["TEST"] : names).forEach(function (n) { var o = mk("option", null, n); o.value = n; sel.appendChild(o); });
    var KEY = R.NS.slice(1) + "_ude_name";
    try { var was = localStorage.getItem(KEY); if (was && names.indexOf(was) >= 0 && !TEST) sel.value = was; } catch (e) { }
    if (TEST) sel.value = "TEST";
    b.type = "button"; b.id = "uvCommentSend"; msg.id = "uvCommentMsg"; msg.setAttribute("role", "status");
    row.appendChild(sel); row.appendChild(b); row.appendChild(msg); sec.appendChild(row);
    b.addEventListener("click", function () {
      var text = ta.value.trim();
      if (!text) { msg.className = "umsg bad"; msg.textContent = "Nothing to send yet. Write your comment in the box."; return; }
      if (!sel.value) { msg.className = "umsg bad"; msg.textContent = "Pick your name first."; return; }
      b.disabled = true; msg.className = "umsg"; msg.textContent = "Sending...";
      try { if (!TEST) localStorage.setItem(KEY, sel.value); } catch (e) { }
      fetch(R.API + "/ude/comment", { method: "POST", headers: auth({ "Content-Type": "application/json" }),
        body: JSON.stringify({ text: text, answered_by: sel.value }) })
        .then(answer)
        .then(function (x) {
          b.disabled = false;
          if (x.s === 200 && x.j && x.j.ok) { ta.value = ""; msg.className = "umsg"; msg.textContent = "Sent " + clock() + ". Thank you."; }
          else if (x.s === 401) { msg.className = "umsg bad"; msg.textContent = "Not sent: signed out. Reload the page and enter the password again. Your words are still in the box."; }
          else { msg.className = "umsg bad"; msg.textContent = "Not sent: " + String((x.j && x.j.error) || ("the server answered " + x.s)).replace(/\.$/, "") + ". Your words are still in the box."; }
        })
        .catch(function () { b.disabled = false; msg.className = "umsg bad"; msg.textContent = "Not sent: the server could not be reached. Your words are still in the box."; });
    });
  }

  /* ---------- the editor's extra: the comments received, newest first ---------- */
  var drawComments = null;
  function loadComments() {
    fetch(R.API + "/ude/history", { headers: auth() }).then(answer).then(function (x) {
      if (x.s === 200 && x.j && x.j.ok && drawComments) drawComments(x.j.comments || []);
    }).catch(function () { });
  }
  function editorExtras() {
    var cs = addSection("uvComments", "Comments received");
    var list = mk("ul"); list.id = "uvCommentList"; cs.appendChild(list);
    drawComments = function (rows) {
      rows = rows.filter(function (c) { return TEST || c.answered_by !== "TEST"; });
      list.textContent = "";
      list.setAttribute("data-count", String(rows.length));
      if (!rows.length) list.appendChild(mk("li", null, "No comments yet."));
      rows.forEach(function (c) {
        var li = mk("li");
        li.appendChild(mk("span", "umeta", R.fmtTs(c.ts_utc) + ", " + c.answered_by));
        li.appendChild(mk("span", "utext", c.text));
        list.appendChild(li);
      });
    };
    loadComments();
  }
})();
